$src['state'] = ['w:work-gloves-b' => true]; $gl = array_column(pfd_tiles(array_values(array_filter(pfd_build($src)['deck'], fn($e) => $e['src'] === 'wear')), ['grit' => 0, 'nimble' => 0, 'hardiness' => 0, 'charm' => 0, 'lore' => 0, 'luck' => 0, 'level' => 3]), null, 'n');
