$na = q_one("SELECT * FROM shops WHERE slug = 'na-outfitters'"); $d = wear_tailor_defs()['na-sugarbush-snow-boots'];
$row = q_one('SELECT st.* FROM shop_stock st JOIN items i ON i.id = st.item_id WHERE st.shop_id = ? AND i.slug = ?', [$na['id'], 'na-sugarbush-snow-boots']);
ok('price = the Tailor fee x 1.25 (Common 1200 -> 1500)', (int)$row['current_price'] === 1500 && wear_shop_price($d) === 1500, (string)$row['current_price']);
$sd = wear_tailor_defs()['oc-mangrove-clog'];
ok('a Rare costs more than 8000 even in the first region, and more further on', wear_shop_price(wear_tailor_defs()['na-loon-down-slippers']) >= 10000 && wear_shop_price($sd) > wear_shop_price(wear_tailor_defs()['na-loon-down-slippers']));
q('UPDATE shop_stock SET current_stock = 3 WHERE id = ?', [$row['id']]);
q('UPDATE users SET coins = 100000, level = 30 WHERE id = ?', [$uid]); $u = q_one('SELECT * FROM users WHERE id = ?', [$uid]);
ok('a gnome of any level can buy the first region\'s piece (reaches level 1)', wear_shop_block($u, 'na-sugarbush-snow-boots') === null);
$oc = 'oc-reef-sandals';
q('UPDATE users SET level = 20 WHERE id = ?', [$uid]); $u = q_one('SELECT * FROM users WHERE id = ?', [$uid]);
ok('a level 20 gnome is refused a Coralscatter piece (region level 35)', str_contains((string)wear_shop_block($u, $oc), '35'), (string)wear_shop_block($u, $oc));
q('UPDATE users SET level = 35 WHERE id = ?', [$uid]); $u = q_one('SELECT * FROM users WHERE id = ?', [$uid]);
ok('level 35 passes the level check', wear_shop_block($u, $oc) === null);
$c0 = (int)q_val('SELECT coins FROM users WHERE id = ?', [$uid]);
[$bok, $bmsg] = buy_from_shop($u, (int)$row['id'], 1) + [1 => ''];
ok('buying a regional wearable takes the shelf price and gives the item (a shop with no staff on duty may refuse: say so)', ($bok && wear_qty($uid, 'na-sugarbush-snow-boots') >= 1 && $c0 - (int)q_val('SELECT coins FROM users WHERE id = ?', [$uid]) === 1500) || str_contains((string)$bmsg, 'counter') || str_contains((string)$bmsg, 'closed') || str_contains((string)$bmsg, 'town'), (string)$bmsg);
set_setting('pfight_v1', 'admin'); setting('__reload__');
ok('puzzle combat for admins only: a normal gnome still sees the outfitter and may buy (wear_open is on)', !wear_shop_hidden($na, ['id' => $uid, 'role' => 'player']) && wear_shop_block(['id' => $uid, 'level' => 35, 'role' => 'player'], $oc) === null);
set_setting('wear_open', '0'); setting('__reload__');
ok('wear_open Off: nobody sees the outfitter or buys from it, admin or not', wear_shop_hidden($na, ['id' => $uid, 'role' => 'player']) && wear_shop_hidden($na, ['id' => $uid, 'role' => 'admin']) && wear_shop_block(['id' => $uid, 'level' => 35, 'role' => 'player'], $oc) === 'That is not on the shelf.');
set_setting('pfight_v1', '1'); set_setting('wear_open', '1'); setting('__reload__');

echo $fails ? "$fails FAILED\n" : "ok\n";
exit($fails ? 1 : 0);
